export function renderAssistant(text: string): string {
  const lines = text.split("\n");
  let inFence = false;
  return lines
    .map((ln) => {
      if (ln.trimStart().startsWith("```")) {
        inFence = !inFence;
        return chalk.dim(ln);
      }
      if (inFence) return chalk.dim(ln);
      if (/^#{1,4}\s/.test(ln)) return chalk.bold.white(ln);
      return ln;
    })
    .join("\n");
}
